            printf(“\n So do doan thang thu nhat: ”);scanf(“%f”,&a);
            printf(“\n So do doan thang thu hai: ”);scanf(“%f”,&b);
            printf(“\n So do doan thang thu ba: ”);scanf(“%f”,&c);
            if ((a+b>c) && (b+c>a) && (a+c>b))
                   { p = (a+b+c)/2;
                       S = sqrt(p*(p-a)*(p-b)*(p-c));
                       printf(“\n Chu vi: %5.2f, dien tich: %5.2f”,p*2,s);
                   }
            else       printf(“\n Khong ton tai tam giac”);
            getch();
        }

