                                         Lệnh1            <biểu_thức>       T
                                                                                 Lệnh1
                   = bt1                                      = bt1

                         F
                                                                F

               <biểu_thức>        T                                         T
                   = bt2
                                         Lệnh2            <biểu_thức>
                                                                                 Lệnh2
                                                              = bt2

                       F
                                                                 F
                     …
                                                              …
                         F
                                                                  F
               <biểu_thức>        T
                   = btn
                                        Lệnhn
                                                          <biểu_thức>      T
                                                              = btn
