              dai = strlen(st);
              for (i=0;i< dai;i++)         /* Đổi dòng ký ký vừa đọc vào thành chữ hoa */
                st[i] = toupper(st[i]);
              for (i=0;i<='Z'-'A'+1;i++) /* Xoá bộ đệm đếm ký tự về 0 */
                  dem[i]=0;
              for (i=0;i< dai;i++) /* Đếm số lượng từng loại ký tự có trong xâu nhập */
                   dem[st[i]-'A']++;
              for (i='A';i<='Z';i++) /* Viết số lượng của từng loại ký tự có trong xâu */
                   if (dem[i-'A'])
                    printf("\n So ky tu %c = %d ",i,dem[i-'A']);
